package ama.api;
import ama.storage.*;import ama.contract.ConfigArchiveContracts.*;import ama.transcript.ControlledKnowledgeClient;import java.nio.file.*;import java.net.URI;import java.util.*;import javax.net.ssl.SSLContext;import org.springframework.boot.test.context.runner.ApplicationContextRunner;import org.springframework.context.support.GenericApplicationContext;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
/** Exact profile diff and real production wiring with public archive admission, zero SQL/RPC. */
class Task11B3BudgetAssemblyTest {
 @Test void finiteProfilesDifferOnlyInTheNamedDiagnosticByteDimension(){var settings=new Task11B3LifecycleApi.Settings(Path.of("public-unit-archive"),"0".repeat(64),new Ref(ArtifactType.PROCESSING_CONFIG,"unit-v1","0".repeat(64)),new Ref(ArtifactType.PROMPT_CONFIG,"unit-v1","0".repeat(64)),new Ref(ArtifactType.MODEL_CONFIG,"unit-v1","0".repeat(64)),Path.of("no-private-identities"),URI.create("http://127.0.0.1:1"),false);var original=Task11B3BudgetApi.properties(settings,Task11B3BudgetApi.Profile.ORIGINAL_1M);var control=Task11B3BudgetApi.properties(settings,Task11B3BudgetApi.Profile.CONTROL_2M);assertEquals(1048576L,original.remove("processing.bounds.archive-total-bytes"));assertEquals(2097152L,control.remove("processing.bounds.archive-total-bytes"));assertEquals(original,control);assertEquals(2,Task11B3BudgetApi.Profile.values().length);}
 @Test void bothProfilesUseActualArchiveAndMetadataCompositionWithoutSqlOrNativeRpc()throws Exception {
  for(var profile:Task11B3BudgetApi.Profile.values()){
   Path workspace=Path.of(System.getenv("AMA_TASK11_REPOSITORY_ROOT"),".superpowers"),archive=Files.createTempDirectory(workspace,"b3-budget-unit-archive-");Files.setPosixFilePermissions(archive,java.nio.file.attribute.PosixFilePermissions.fromString("rwx------"));var source=new Task11B3LifecycleAssemblyTest.NoSql();var storage=new LocalFileClient(URI.create("https://localhost:1"),SSLContext.getDefault());var binding=new ManagedBackendId.Local("https://localhost:1","offline-budget-volume","unit","overlay");var definitions=new FileBackendDefinitions(List.of(new FileBackendCatalog.Backend(binding.id(),"local",1,"WRITABLE",storage,binding)),binding.id());
   try{var settings=new Task11B3LifecycleAssemblyTest().settings(archive,false);var values=Task11B3BudgetApi.properties(settings,profile);values.remove("publication.client-identities");String[] properties=values.entrySet().stream().map(e->e.getKey()+"="+e.getValue()).toArray(String[]::new);new ApplicationContextRunner().withUserConfiguration(Task11B3BudgetApi.Wiring.class).withInitializer(context->Task11B3LifecycleApi.infrastructure((GenericApplicationContext)context,source,definitions)).withPropertyValues(properties).withBean(ControlledKnowledgeClient.class,()->mock(ControlledKnowledgeClient.class)).run(context->{if(context.getStartupFailure()!=null)throw new AssertionError("Actual diagnostic composition",context.getStartupFailure());assertNotNull(Task11RuntimeProbe.publication(context));assertNotNull(Task11RuntimeProbe.localPublication(context));assertEquals(0,source.calls.get());assertTrue(context.getBeansOfType(ama.worker.WorkerLoop.class).isEmpty());assertTrue(context.getBeansOfType(ama.worker.ReconciliationLoop.class).isEmpty());});}
   finally{try{Task11B3LifecycleApi.closeOwnedNativeClient(storage);}finally{assertTrue(archive.toRealPath().startsWith(workspace.toRealPath())&&archive.getFileName().toString().startsWith("b3-budget-unit-archive-"));try(var stream=Files.walk(archive)){for(Path path:stream.sorted(Comparator.reverseOrder()).toList())Files.delete(path);}}}
  }
 }
}